var host=$("meta[name='home_url']").attr("content");(function(){"use strict";$.get(host+"/get-aside",function(t,i){$(".aside-block").html(t);const e=document.querySelector("#phone-field2"),n=document.querySelector("#fullphone-field2"),u=window.intlTelInput(e,{initialCountry:"ae",separateDialCode:!0});e.addEventListener("keyup",()=>{const o=u.getNumber();n.value=o})})})();
